// Real narration files (neural Indian voice, generated by scripts/make-audio.py) are hosted on a
// GitHub Release so the app stays free to run. Same ids as the audio/ folder layout.
export const AUDIO_BASE = (import.meta.env.VITE_AUDIO_BASE as string | undefined)
  ?? 'https://github.com/monish-ui/mahabharat-katha/releases/download/audio-v1'

export const audioUrl = {
  shloka: (verse: string) => `${AUDIO_BASE}/gita_${verse}.mp3`,
  chapter: (n: number) => `${AUDIO_BASE}/gita-ch_${n}.mp3`,
  story: (parvaSlug: string, storySlug: string) => `${AUDIO_BASE}/katha_${parvaSlug}--${storySlug}.mp3`
}
